const fs = require('fs');
const path = require('path');

// Read the CSV file
const filePath = path.join(__dirname, 'readings.csv');
if (!fs.existsSync(filePath)) {
  console.error('Error: File not found:', filePath);
  process.exit(1);
}

const content = fs.readFileSync(filePath, 'utf8');
const lines = content.split('\n');

// Parse CSV: read each line, split by comma, and extract the temp column
const tempColumn = lines
  .map(line => line.split(','))
  .filter(row => row.length > 0)
  .map(row => row[1])
  .filter(val => !isNaN(val));

if (tempColumn.length === 0) {
  console.error('Error: No valid data in the temp column.');
  process.exit(1);
}

// Calculate average
const average = tempColumn.reduce((a, b) => a + b, 0) / tempColumn.length;

// Print the result
console.log(`Average of the temp column: ${average.toFixed(2)}`);
END

